function grade(score) {
  if (score >= 90) {
    return "A";
  } else if (score >= 80) {
    return "B";
  } else if (score >= 70) {
    return "C";
  } else {
    return "F";
  }
}

console.log(grade(95)); // A
console.log(grade(72)); // C

items.body:
Loops repeat code. The classic `for` loop has three parts: a start, a condition to keep going, and a step:

~~~
for (let i = 1; i <= 3; i++) {
  console.log(i);
}
// 1, 2, 3
~~~

`i++` means "add 1 to i". A common pattern is to keep a running total:

~~~
let total = 0;
for (let i = 1; i <= 3; i++) {
  total += i;   // same as total = total + i
}
~~~

