items.solution:
function sumTo(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) {
    total += i;
  }
  return total;
}

console.log(sumTo(4)); // 10

items.body:
An **array** is an ordered list of values:

~~~
const colors = ["red", "green", "blue"];
console.log(colors[0]);      // "red" (counting starts at 0!)
console.log(colors.length);  // 3
colors.push("purple");       // add to the end
~~~

Use `for...of` to loop over every item:

~~~
for (const color of colors) {
  console.log(color);
}
~~~

items.starter:
function largest(nums) {
  let biggest = nums[0];

  return biggest;
}

console.log(largest([3, 9, 2])); // 9

items.solution:
function largest(nums) {
  let biggest = nums[0];
  for (const n of nums) {
    if (n > biggest) {
      biggest = n;
    }
  }
  return biggest;
}

console.log(largest([3, 9, 2])); // 9

const book = {
  title: "Dune",
  author: "Frank Herbert",
  pages: 412,
};

function describe(b) {
  return `${b.title} by ${b.author}`;
}

console.log(describe(book));

function evensDoubled(nums) {
  return nums
    .filter(n => n % 2 === 0)
    .map(n => n * 2);
}

console.log(evensDoubled([1, 2, 3, 4])); // [4, 8]

